'use strict';
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),D=window.GAECHEON_DATA;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const activityByGrade={};
const freshActivity=()=>({order:[],classes:{},choice:null,reflection:'',drafts:{}});
const state={grade:'3-4',index:0,beat:0,selected:null,microSelected:null,soundOn:false,view:'home',answers:{},activity:freshActivity()};
const labels={story:'전해지는 이야기',history:'전승과 역사',evidence:'자료의 단서',quiz:'골든벨',fact:'알아보기',value:'오늘의 실천',activity:'학생 참여',source:'문헌 탐구',inquiry:'주장과 근거',cover:'시작하기',exit:'배움 정리',observe:'이미지 관찰',youtube:'유튜브 영상',sequence:'이야기 순서',today:'오늘의 개천절',timeline:'국경일이 된 길',reading:'원문 읽기',law:'기록으로 본 역사',classwork:'교실 활동'};
function route(){const choice=location.hash.match(/^#choose\/(1-2|3-4|5-6)$/);if(choice){history.replaceState(null,'',`#lesson/${choice[1]}/0`);route();return}if(modal.open)modal.close();const m=location.hash.match(/^#(lesson|student)\/(1-2|3-4|5-6)(?:\/(\d+))?/);if(m){state.view=m[1];activityByGrade[state.grade]=state.activity;state.grade=m[2];state.activity=activityByGrade[state.grade]||freshActivity();activityByGrade[state.grade]=state.activity;if(m[1]==='student'&&m[3]!==undefined)state.activity.tab=['story','class','act'][Number(m[3])]||'story';state.index=Math.min(Math.max(0,Number(m[3]||0)),D.grades[state.grade].slides.length-1);state.beat=0;state.selected=null;state.microSelected=null;render()}else{state.view='home';window.LessonLibrary?.clear('gaecheon');render()}}
function home(){document.body.className='home-mode';app.innerHTML=`<header class="g-head"><a href="index.html" class="g-brand"><b>ㄱ</b><span>오늘의 국경일<small>개천절 교육자료</small></span></a><a href="index.html" class="head-link">← 다섯 국경일</a></header><main id="main" class="g-home"><section class="g-hero"><img src="assets/gaecheon-tree.png" alt="한국의 능선 위 큰 나무 곁으로 아침 해가 떠오르는 생성 삽화"><div class="g-hero-wash"></div><div class="g-hero-copy"><span class="overline">OCTOBER 03 · NATIONAL FOUNDATION DAY</span><h1>하늘이 열린 이야기,<br><em>사람을 이롭게 하는 마음.</em></h1><p>개천절의 전승과 고조선의 역사를 구분하며<br>우리 교실에서 홍익인간의 뜻을 찾아봅니다.</p></div></section><section class="grade-chooser"><div class="chooser-heading"><span class="overline dark">CHOOSE YOUR CLASS</span><h2>우리 반의 배움 길을 골라 주세요</h2><p>학년을 고르면 모든 장면을 순서대로 볼 수 있어요. 학습지와 해설은 수업 화면에서 열어 주세요.</p></div><div class="grade-cards">${Object.entries(D.grades).map(([id,g],i)=>`<a class="grade-card" href="#lesson/${id}/0"><div class="grade-art"><img src="assets/${['gaecheon-bear-tiger','gaecheon-tree','gaecheon-community'][i]}.png" alt="${['곰과 범의 상상 삽화','산의 나무를 표현한 삽화','청동기 마을의 교육용 재구성'][i]}"></div><div class="grade-meta"><span>${g.label}</span><strong>0${i+1}</strong></div><h3>${esc(g.subtitle)}</h3><p>${esc(g.focus)}</p><div class="grade-foot"><span>${g.slides.length}개 자료·활동</span><b>수업 시작 ↗</b></div></a>`).join('')}</div><aside class="fact-strip"><b>교사를 위한 역사 표현 기준</b><p>개천절은 10월 3일. 하늘이 열렸다는 이야기와 고조선의 시작을 기립니다. 기념일인 10월 3일과 이야기 속 장면을 고대의 확정된 사실처럼 설명하지 않습니다.</p><button data-action="sources">근거 자료 보기 ↗</button></aside></section><footer class="g-footer"><span>학생 활동 응답은 저장·전송하지 않음</span><a href="index.html">국경일 모아 보기 ↗</a></footer></main>`}
const clockText=t=>`${Math.floor(t/60)}:${String(t%60).padStart(2,'0')}`;
function youtubePanel(s){const y=s.youtube;return `<img class="slide-photo" src="assets/${esc(s.image)}.png" alt=""><figure class="yt-figure"><div class="yt-frame"><iframe src="https://www.youtube-nocookie.com/embed/${esc(y.id)}?start=${y.start}&amp;end=${y.end}&amp;rel=0&amp;playsinline=1&amp;hl=ko" title="${esc(y.title)}" allow="encrypted-media; picture-in-picture; fullscreen" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div><figcaption><span>${esc(y.channel)} · ${clockText(y.start)}–${clockText(y.end)} 구간</span><a href="https://www.youtube.com/watch?v=${esc(y.id)}&amp;t=${y.start}s" target="_blank" rel="noopener noreferrer">YouTube에서 열기 ↗</a></figcaption></figure>`}
// The intro video is a local file: no ads, works offline, and the teacher starts it with the player controls.
function documentaryPanel(s){const v=s.documentary;return `<img class="slide-photo" src="assets/${esc(s.image)}.png" alt=""><figure class="yt-figure"><div class="yt-frame"><video class="doc-video" src="videos/${esc(v.file)}.mp4?v=20261001-story4" poster="assets/${esc(v.poster)}.png" controls playsinline preload="metadata" aria-label="${esc(v.title)}"></video></div><figcaption><span>직접 만든 교육용 영상 · 1분 · 광고 없음</span><button data-action="notes">영상 대본 보기</button></figcaption></figure>`}
function picture(s){if(s.artifact)return `<figure class="artifact-visual"><img src="assets/${esc(s.artifact.file)}" alt="${esc(s.artifact.alt)}"><figcaption>${esc(s.artifact.title)}<br>${esc(s.artifact.credit)}<br><a href="${esc(s.artifact.url)}" target="_blank" rel="noopener noreferrer">소장품 정보 · 출처 ↗</a><br><button data-action="dolmen-compare">고인돌 사진과 그림 비교</button></figcaption></figure>`;if(s.youtube)return youtubePanel(s);if(s.documentary)return documentaryPanel(s);return `<img class="slide-photo" src="assets/${esc(s.image)}.png" alt="${esc(s.kind==='story'?'전승을 상상하여 표현한 삽화':s.kind==='history'||s.kind==='evidence'?'자료를 참고한 교육용 재구성':'개천절 교육용 생성 삽화')}">${s.video?`<video class="slide-video" src="videos/${esc(s.video)}.mp4" poster="assets/${esc(s.image)}.png" playsinline preload="auto" aria-hidden="true"></video>`:''}${s.kind==='inquiry'?'<img class="skia-card" src="assets/gaecheon-fact-skia.png" alt="10월 3일은 기념하는 날이며 정확한 고대 사건 날짜로 확정되지 않았음을 알리는 타이포그래픽">':''}`}
function choices(s){if(!s.choices)return'';return `<div class="quiz-choices ${typeof s.choices[0]==='object'?'picture-options':''}">${s.choices.map((x,i)=>{const obj=typeof x==='object'?x:{text:x};return `<button class="quiz-choice ${state.selected===i?'picked':''} ${state.beat&&i===s.correct?'correct':''} ${state.beat&&state.selected===i&&i!==s.correct?'wrong':''}" data-choice="${i}" aria-pressed="${state.selected===i}" ${state.beat?'disabled':''}><span class="choice-index">${i+1}</span>${obj.image?`<img src="assets/${esc(obj.image)}.png" alt="">`:''}<span>${esc(obj.text)}</span></button>`}).join('')}</div>`}
function kineticTitle(value){return String(value).split(/\s+/).map((word,i)=>`<span class="kinetic-word" style="--word-index:${i}">${esc(word)}</span>`).join(' ')}
// `correct` marks the right option, so it is not always the first one; a slide may override with `micro`.
const microPrompts={
 observe:{label:'눈으로 찾은 단서',choices:['여기에 누가 살았을 것 같다','산과 나무가 보인다'],correct:1,explain:'보이는 것과 이야기로 짐작한 것을 나누어 말해 보세요.'},
 source:{label:'기록의 성격',choices:['후대에 편찬된 문헌','고조선 당시의 기록'],correct:0,explain:'『삼국유사』는 단군 이야기보다 훨씬 뒤인 고려 시대에 편찬된 문헌이에요.',wrongExplain:'고조선 당시 사람이 바로 남긴 기록은 아니에요. 『삼국유사』는 고려 시대에 편찬되었어요.'},
 evidence:{label:'그림의 성격',choices:['특정 발굴 현장의 사진','교육용 상상 재구성'],correct:1,explain:'그림은 사료 원본이나 발굴 사진이 아니에요.'},
 inquiry:{label:'10월 3일의 의미',choices:['옛 기록에 적힌 건국일','오늘 기념하는 날짜'],correct:1,explain:'옛 기록에는 건국한 달과 날이 없어요. 10월 3일은 오늘 기념하는 날짜예요.'},
 value:{label:'우리 반의 실천',choices:['의견을 듣고 함께 돕기','친구 대신 모두 결정하기'],correct:0,explain:'도움받는 사람의 뜻을 존중하는 것이 중요해요.'}
};
function microFeedback(s){const a=s.artifact?null:s.micro||microPrompts[s.kind];if(!a)return'';if(state.microSelected===null)return esc(a.explain);const correct=state.microSelected===a.correct;return `<b>${correct?'잘 찾았어요.':'다시 살펴봐요.'}</b> ${esc(!correct&&a.wrongExplain?a.wrongExplain:a.explain)}`}
function microActivity(s){const a=s.artifact?null:s.micro||microPrompts[s.kind];if(!a)return'';const selected=state.microSelected!==null;return `<div class="micro-activity" aria-label="교실 참여 질문"><span class="micro-label">● 함께 눌러 보기 · ${esc(a.label)}</span><div class="micro-options">${a.choices.map((choice,i)=>`<button data-micro="${i}" aria-pressed="${state.microSelected===i}" class="micro-option ${state.microSelected===i?'chosen':''} ${(state.beat||state.microSelected===i)&&i===a.correct?'right':''} ${state.microSelected===i&&i!==a.correct?'wrong':''}" ${state.beat?'disabled':''}><span>${i+1}</span>${esc(choice)}</button>`).join('')}</div><p class="micro-explain" role="status" aria-live="polite" ${state.beat||selected?'':'hidden'}>${state.beat||selected?microFeedback(s):''}</p></div>`}
function selectMicro(index){const s=D.grades[state.grade].slides[state.index],a=s.artifact?null:s.micro||microPrompts[s.kind];if(state.view!=='lesson'||state.beat||!a||!Number.isInteger(index)||index<0||index>=a.choices.length)return;state.microSelected=index;const root=app.querySelector('.micro-activity');if(!root)return;root.querySelectorAll('[data-micro]').forEach(b=>{const i=Number(b.dataset.micro),picked=i===index;b.classList.toggle('chosen',picked);b.classList.toggle('right',picked&&i===a.correct);b.classList.toggle('wrong',picked&&i!==a.correct);b.setAttribute('aria-pressed',String(picked))});const feedback=root.querySelector('.micro-explain');feedback.innerHTML=microFeedback(s);feedback.hidden=false;}
// Richer scenes: a storybook paragraph before the question, then timeline, cards, steps or a picture order.
const narration=s=>s.narration?`<p class="slide-narration">${esc(s.narration)}</p>`:'';
function richBlocks(s){
 const timeline=s.timeline?`<ol class="slide-timeline">${s.timeline.map(t=>`<li><b>${esc(t.year)}</b><span>${esc(t.text)}</span></li>`).join('')}</ol>`:'';
 const cards=s.cards?`<div class="slide-cards">${s.cards.map(c=>`<article class="slide-card"><b>${esc(c.title)}</b><p>${esc(c.text)}</p>${c.sub?`<small>${esc(c.sub)}</small>`:''}</article>`).join('')}</div>`:'';
 const steps=s.steps?`<ol class="slide-steps">${s.steps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol>`:'';
 const sequence=s.sequence?`<div class="sequence-grid sequence-four">${(s.sequenceOrder||s.sequence.map((_,i)=>i)).map(i=>`<figure class="sequence-card"><img src="assets/${esc(s.sequence[i].image)}.png" alt="${esc(s.sequence[i].alt||'옛이야기 사건 삽화')}"><figcaption><span class="sequence-number">${state.beat?i+1:'?'}</span>${esc(s.sequence[i].text)}</figcaption></figure>`).join('')}</div>`:'';
 // A single example card sits beside the steps so short screens keep the answer in view.
 const pair=s.steps&&s.cards?.length===1?`<div class="rich-row">${cards}${steps}</div>`:cards+steps;
 return timeline+pair+sequence;
}
const slideLinks=s=>s.links?.length?`<div class="slide-links" aria-label="실제 자료 보기">${s.links.map(l=>`<a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.title)} <span aria-hidden="true">↗</span></a>`).join('')}</div>`:'';
function slide(){
 const g=D.grades[state.grade],s=g.slides[state.index],path=window.LessonLibrary?.path('gaecheon',state.grade)||g.slides.map((_,i)=>i),count=path.length,step=path.indexOf(state.index)+1;
 window.LessonLibrary?.record('gaecheon',state.grade,state.index);
 document.body.className='presenter-mode';
 app.innerHTML=`<div class="presenter-shell" id="main"><header class="presenter-head"><a href="index.html" class="mini-brand">ㄱ <span>국경일 모아 보기</span></a><div class="presenter-context"><b>개천절</b><span>${g.label} · ${esc(g.subtitle)}</span></div><div class="presenter-tools"><button data-action="replay" title="현재 장면의 영상과 글자 모션 다시 보기">↺ 다시 보기</button>${s.video?`<button data-action="sound" title="영상 배경음 켜기 또는 끄기">${state.soundOn?'♫ 소리 켜짐':'♫ 소리 켜기'}</button>`:''}<button data-action="contents">학습지·해설</button><button data-action="qr">학생 QR</button><button data-action="notes" title="교사용 발문과 정확한 표현">교사 노트</button><button data-action="sources" title="공식 근거 자료">자료 출처</button><button data-action="full" title="전자칠판 전체 화면">⛶ 전체 화면</button></div></header><section class="slide-canvas scene-${esc(s.kind)}${s.youtube||s.documentary?' has-player':s.artifact?' has-artifact':''} phase-${state.beat}" aria-label="${esc(s.title)}"><div class="slide-image">${picture(s)}</div><div class="slide-content ${state.beat?'reveal-phase':'animate'}" id="motion-content"><span class="slide-kicker"><i></i>${esc(s.tag||labels[s.kind])}</span><div class="slide-main"><span class="slide-number">${String(step).padStart(2,'0')} <i>/</i> ${String(count).padStart(2,'0')}</span><h1>${kineticTitle(s.title)}</h1>${narration(s)}<p class="slide-question">${esc(s.question)}</p>${richBlocks(s)}${slideLinks(s)}${choices(s)}${microActivity(s)}${s.kind==='activity'?`<button class="qr-inline" data-action="qr">학생 태블릿 활동 열기 <span>↗</span></button>`:''}<div class="answer ${state.beat?'visible':''}" aria-live="polite"><b>${s.kind==='quiz'?'정답과 이유':'함께 정리'}</b><p>${esc(s.answer)}</p></div></div><div class="slide-bottom"><span class="step-guide">${state.beat?'설명과 이유를 나누어 주세요':'먼저 학생의 생각을 들어 주세요'}</span><span>목표에 맞춰 탐구해요</span></div></div></section><footer class="presenter-foot"><div class="foot-left"><span class="progress-label">전체 장면</span><div class="progress"><span style="width:${Math.min(100,((step-1+(state.beat?1:.5))/count)*100)}%"></span></div><b>${step} / ${count}</b></div><div class="foot-controls"><button data-action="prev" ${step===1&&!state.beat?'disabled':''}>← 이전</button><button class="next" data-action="next">${state.beat?(step===count?'활동 마치기':'다음 장면 →'):'설명 보기 →'}</button></div></footer></div>`;
 const video=app.querySelector('.slide-video');if(video){video.muted=!state.soundOn;video.volume=.65;video.play().catch(()=>{video.muted=true;state.soundOn=false;video.play().catch(()=>{});const sound=app.querySelector('[data-action="sound"]');if(sound)sound.textContent='♫ 소리 켜기'})}
}

function student(){const g=D.grades[state.grade];document.body.className='student-mode';app.innerHTML=`<header class="student-head"><a href="index.html">ㄱ 오늘의 국경일</a><span>개천절 · ${g.label}</span></header><main id="main" class="student-main"><div class="student-title"><span class="overline dark">TABLET ACTIVITY</span><h1>나의 개천절 탐험</h1><p>자료를 보고 먼저 생각한 뒤, 짝에게 이유를 말하고 내 생각을 고쳐 보세요.</p></div><nav class="activity-tabs"><button data-tab="story" class="${state.activity.tab!=='class'&&state.activity.tab!=='act'?'on':''}">① ${state.grade==='1-2'?'이야기':state.grade==='3-4'?'자료 비교':'주장 수정'}</button><button data-tab="class" class="${state.activity.tab==='class'?'on':''}">② 자료 구분</button><button data-tab="act" class="${state.activity.tab==='act'?'on':''}">③ 우리 반 실천</button></nav><div class="activity-panel">${activityBody()}</div><p class="privacy">이 활동은 학생 이름이나 응답을 서버로 보내지 않습니다. 교사에게 말이나 학습지로 공유해 주세요.</p></main>`}
// 1–2 read-aloud: buttons appear only when the browser can speak, and each press stops the previous sentence.
const canSay=()=>'speechSynthesis' in window&&typeof SpeechSynthesisUtterance!=='undefined';
const sayButton=text=>canSay()?`<button class="say-button" data-say="${esc(text)}" aria-label="읽어 주기: ${esc(text)}">🔊 읽어 주기</button>`:'';
function say(text){try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ko-KR';u.rate=.9;speechSynthesis.speak(u)}catch{}}
const tabHeading=(title,help,plain=help)=>`<div class="tab-heading"><h2>${esc(title)}</h2>${sayButton(`${title} ${plain}`)}</div><p>${help}</p>`;
function activityBody(){const inquiry=window.gaecheonInquiryBody?.(state.activity.tab||'story');if(inquiry)return inquiry;const a=state.activity,g=state.grade,young=g==='1-2',tab=a.tab||'story';if(tab==='story'){const order=D.storyOrder,items=D.storyCards.map(c=>[c.label,c.image]),done=a.order.length===items.length,right=a.order.join(',')===D.storyCards.map((_,i)=>i).join(',');return `${young?tabHeading('이야기를 순서대로 놓아 볼까요?','그림을 눌러 차례대로 고르세요. 모든 그림은 <b>옛이야기를 상상해서 그린 그림</b>이에요.','그림을 눌러 차례대로 고르세요. 모든 그림은 옛이야기를 상상해서 그린 그림이에요.'):tabHeading('이야기를 순서대로 놓아 볼까요?','그림을 눌러 차례대로 고르세요. 모든 장면은 <b>전해지는 이야기나 교육용 상상 그림</b>입니다.')}<div class="student-grid story-four">${order.map(i=>`<button class="story-option ${a.order.includes(i)?'chosen':''}" data-story="${i}" ${a.order.includes(i)?'disabled':''}><img src="assets/${items[i][1]}.png" alt=""><span>${items[i][0]}</span></button>`).join('')}</div><div class="selected-sequence">내가 고른 순서: ${a.order.map(i=>items[i][0]).join(' → ')||'아직 없음'}</div><div class="activity-actions"><button data-action="story-reset">다시 고르기</button>${done?`<span class="feedback ${right?'good':'again'}">${right?'잘했어요! 이야기의 흐름을 짝에게 설명해 보세요.':'순서를 다시 생각해 보세요. 환웅이 내려오는 이야기부터 시작해요.'}</span>`:''}</div>`}
if(tab==='class'){const questions=young?[['곰이 사람이 되었다는 이야기','전승'],['개천절은 해마다 10월 3일에 기념해요','사실']]:g==='3-4'?[['『삼국유사』에 단군 이야기가 적혀 있다','사실'],['곰이 사람으로 변했다는 이야기','전승'],['화면 속 마을 그림','상상']]:[['『삼국유사』는 단군 이야기를 전한다','사실'],['단군왕검이 고조선을 세웠다는 이야기','전승'],['1949년 법으로 개천절을 양력 10월 3일로 정했다','사실'],['이 화면의 마을 그림','상상'],['비파형 동검은 출토된 유물이다','사실']],kinds=young?[['사실','진짜 있는 일'],['전승','옛이야기']]:['사실','전승','상상'].map(v=>[v,v]);return `${young?tabHeading('진짜 있는 일일까, 옛이야기일까?','문장을 듣고 알맞은 쪽을 골라 보세요.'):tabHeading('사실, 전승, 상상 그림','각 문장을 살펴보고 알맞은 종류를 골라 보세요. ‘전승’은 옛이야기로 전해지는 내용이에요.')}<div class="class-list">${questions.map(([q,correct],i)=>`<div class="class-row"><div class="say-line"><b>${esc(q)}</b>${sayButton(q)}</div><div>${kinds.map(([v,label])=>`<button data-class="${i}" data-value="${v}" class="${a.classes[i]===v?'on':''}">${label}</button>`).join('')}</div>${a.classes[i]?`<small class="${a.classes[i]===correct?'good':'again'}">${a.classes[i]===correct?'좋아요. 까닭을 설명해 보세요.':young?'다시 생각해 보세요. 옛이야기 속 일인지, 오늘 정말 있는 일인지 살펴봐요.':'다시 살펴보세요. 기록·실제 유물·상상 삽화를 구분해요.'}</small>`:''}</div>`).join('')}</div>`}
const options=young?['친구가 싫다는데 대신 다 해 줘요','친구와 함께 교실을 정리해요','도와준 일을 자랑해요']:['친구의 생각을 묻지 않고 대신 결정해요','좋아 보이게 사진만 찍어요','도움이 필요한 사람의 의견을 듣고 함께 방법을 정해요'],right=young?1:2;return `${tabHeading('우리 반에서 홍익인간','사람을 널리 이롭게 한다는 뜻을 오늘의 행동으로 바꿔 봅시다.')}<div class="action-choices">${options.map((o,i)=>`<div class="action-row"><button data-act="${i}" class="${a.choice===i?'on':''}">${esc(o)}</button>${sayButton(o)}</div>`).join('')}</div>${a.choice!==null?`<div class="feedback ${a.choice===right?'good':'again'}">${a.choice===right?'상대의 생각을 존중하며 돕는 행동이에요.':'그 행동이 모두에게 이로울지 다시 생각해 보세요.'}</div>`:''}<label class="reflection">내가 해 볼 한 가지 행동<textarea data-reflection placeholder="예: 친구의 의견을 듣고 함께 정리하기">${esc(a.reflection)}</textarea></label><p class="save-note">적은 내용은 저장되지 않고 새로고침하면 지워져요. 친구나 선생님에게 직접 말해 주세요.</p>`}
function openModal(body){modal.innerHTML=`<button class="close-modal" data-action="close" aria-label="닫기">×</button>${body}`;modal.showModal()}
function sourceList(){openModal(`<span class="overline dark">HISTORICAL SOURCES</span><h2>사실과 전승의 근거</h2><p>개천절의 법적 의미, 단군 이야기의 출처, 청동기 유물의 범위를 구분했습니다.</p><ul class="source-list">${D.sources.map(x=>`<li><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)} ↗</a></li>`).join('')}</ul><p class="source-caveat">초등용 자료의 ‘기원전 2333년’, ‘곰·범 부족’ 같은 문장은 수업에서 “~라고 전해요”, “~로 해석하기도 해요”로 바꿔 말합니다. 백과사전 ‘개천절’의 ‘서기전 2457년’, ‘음력 10월 3일 건국’은 대종교 기년입니다.</p><p class="source-caveat">모든 삽화는 생성한 교육용 상상 그림입니다. 정확한 고대 복식이나 건물, 사건 날짜의 증거로 쓰지 않습니다.</p>`)}
function qr(){window.ActivityQr?.open('gaecheon')}
function render(){if(state.view==='lesson')slide();else if(state.view==='student')student();else{home();const grid=document.querySelector('.grade-cards');grid?.insertAdjacentHTML('afterend',`<div class="worksheet-links"><div><strong>인쇄 학습지</strong><span>학생용과 교사용 해설 · 각 2쪽</span></div>${Object.keys(D.grades).map(id=>`<div class="worksheet-grade"><b>${D.grades[id].label}</b><a href="worksheets/gaecheon-${id}-student.pdf" target="_blank" rel="noopener">학생용 ↗</a><a href="worksheets/gaecheon-${id}-teacher.pdf" target="_blank" rel="noopener">교사용 ↗</a></div>`).join('')}</div>`)}}
// A full re-render would reload the YouTube player or restart the intro video, so player scenes only swap the reveal state.
function showBeat(){const g=D.grades[state.grade],s=g.slides[state.index];if(!(s.youtube||s.documentary)||!app.querySelector('.yt-frame')){render();return}const path=window.LessonLibrary?.path('gaecheon',state.grade)||g.slides.map((_,i)=>i),count=path.length,step=path.indexOf(state.index)+1,beat=!!state.beat,content=app.querySelector('.slide-content');app.querySelector('.slide-canvas').classList.replace(beat?'phase-0':'phase-1',beat?'phase-1':'phase-0');content.classList.toggle('reveal-phase',beat);content.classList.toggle('animate',!beat);app.querySelector('.answer').classList.toggle('visible',beat);app.querySelector('.step-guide').textContent=beat?'설명과 이유를 나누어 주세요':'먼저 학생의 생각을 들어 주세요';app.querySelector('.progress span').style.width=`${((state.index+state.beat/2+1)/count)*100}%`;app.querySelector('[data-action="next"]').textContent=beat?(step===count?'수업 마치기':'다음 장면 →'):'설명 보기 →';app.querySelector('[data-action="prev"]').disabled=step===1&&!beat}
function next(){const slides=D.grades[state.grade].slides;if(!state.beat){state.beat=1;showBeat();return}const following=window.LessonLibrary?window.LessonLibrary.adjacent('gaecheon',state.grade,state.index,1):state.index+1;if(following!==undefined&&following<slides.length){state.index=following;state.beat=0;state.selected=null;state.microSelected=null;history.replaceState(null,'',`#lesson/${state.grade}/${state.index}`);render()}else location.hash=''}
function prev(){if(state.beat){state.beat=0;showBeat();return}const previous=window.LessonLibrary?window.LessonLibrary.adjacent('gaecheon',state.grade,state.index,-1):state.index-1;if(previous!==undefined&&previous>=0){state.index=previous;state.beat=0;state.selected=null;state.microSelected=null;history.replaceState(null,'',`#lesson/${state.grade}/${state.index}`);render()}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.say!==undefined){say(b.dataset.say);return}if(b.dataset.choice!==undefined){state.selected=Number(b.dataset.choice);document.querySelectorAll('.quiz-choice').forEach((x,i)=>x.classList.toggle('picked',i===state.selected));return}if(b.dataset.micro!==undefined){selectMicro(Number(b.dataset.micro));return}if(b.dataset.tab){state.activity.tab=b.dataset.tab;render();document.querySelector(`[data-tab="${state.activity.tab}"]`)?.focus({preventScroll:true});return}if(b.dataset.story!==undefined){state.activity.order.push(Number(b.dataset.story));render();return}if(b.dataset.class!==undefined){state.activity.classes[b.dataset.class]=b.dataset.value;render();document.querySelector(`[data-class="${b.dataset.class}"][data-value="${b.dataset.value}"]`)?.focus({preventScroll:true});return}if(b.dataset.act!==undefined){state.activity.choice=Number(b.dataset.act);render();document.querySelector(`[data-act="${b.dataset.act}"]`)?.focus({preventScroll:true});return}switch(b.dataset.action){case'dolmen-compare':{modal.innerHTML=`<h2>고인돌 자료 비교</h2>${window.dolmenComparison()}<button data-action="close">닫기</button>`;modal.showModal();break}case'next':next();break;case'prev':prev();break;case'story-reset':state.activity.order=[];render();break;case'qr':qr();break;case'contents':window.LessonLibrary?.open('gaecheon',state.grade);break;case'notes':{const s=D.grades[state.grade].slides[state.index];document.querySelector('.doc-video')?.pause();openModal(`<span class="overline dark">TEACHER'S NOTE</span><h2>${esc(s.title)}</h2><p class="note-lead">${esc(s.note)}</p><p><b>학생에게 건넬 질문</b><br>${esc(s.question)}</p><p><b>정리할 말</b><br>${esc(s.answer)}</p>${s.documentary?`<p><b>영상 대본 (화면 글자 그대로)</b></p><ol class="doc-script">${s.documentary.script.map(([t,x])=>`<li><b>${esc(t)}</b><span>${esc(x)}</span></li>`).join('')}</ol>`:''}<p class="source-caveat">영상 없이 그림과 말만으로 진행 가능</p>`);break}case'sources':sourceList();break;case'close':modal.close();break;case'full':try{document.fullscreenElement?await document.exitFullscreen():await document.documentElement.requestFullscreen()}catch{}break;case'sound':{state.soundOn=!state.soundOn;const video=document.querySelector('.slide-video');if(video){video.muted=!state.soundOn;video.volume=.65;video.play().catch(()=>{})}b.textContent=state.soundOn?'♫ 소리 켜짐':'♫ 소리 켜기';break}case'replay':{const el=document.querySelector('#motion-content');if(el){el.classList.remove('animate');void el.offsetWidth;el.classList.add('animate')}const video=document.querySelector('.slide-video');if(video){video.currentTime=0;video.play().catch(()=>{})}const doc=document.querySelector('.doc-video');if(doc){doc.currentTime=0;doc.play().catch(()=>{})}const frame=document.querySelector('.yt-frame iframe');if(frame)frame.src=frame.src;break}}});
document.addEventListener('input',e=>{if(e.target.matches('[data-reflection]'))state.activity.reflection=e.target.value});
document.addEventListener('keydown',e=>{if(state.view!=='lesson'||modal.open||document.querySelector('dialog[open]')||e.target.closest?.('button,a,input,textarea,select,video,audio,[role="button"],[contenteditable="true"]')||e.target.isContentEditable)return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();next()}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();prev()}});
window.ActivityQr?.register('gaecheon',{file:'gaecheon.html',grade:()=>state.grade,label:()=>D.grades[state.grade].label,current:()=>({story:0,class:1,act:2}[state.activity.tab]??0),targets:()=>[{id:0,label:'이야기·자료 탐구'},{id:1,label:'자료 종류와 근거'},{id:2,label:'우리 반 실천'}],modal:openModal});
window.LessonLibrary?.register('gaecheon',{title:'개천절',pdf:'gaecheon',grades:D.grades,start(grade,index){activityByGrade[state.grade]=state.activity;state.grade=grade;state.activity=activityByGrade[grade]||freshActivity();activityByGrade[grade]=state.activity;state.index=index;state.view='lesson';state.beat=0;state.selected=null;state.microSelected=null;history.replaceState(null,'',`#lesson/${grade}/${index}`);render()}});
window.addEventListener('hashchange',route);route();
